def slug(s):
    return re.sub(r'[^a-z0-9]+', '-', s.lower()).strip('-')

def add(book, key, pages, section, content, typ, state, problem, fix='None.', *, severity='P2', frequency=2, friction=3, path='', queries=None, tableids=None, code=None, solutions=None, workflows=None, printed=None, notes='', need=None, searchable=None, context='no', view=None):
    pages = list(pages) if isinstance(pages, (list, range, tuple)) else [pages]
    if printed is None:
        printed = ', '.join(str(p - 2) for p in pages) if book in ['feretory', 'heretic'] and all(p >= 5 and p < 66 for p in pages) else 'Unnumbered / fold or cover; see page ledger'
    green = state in ['RESOLVED', 'PDF_APPROPRIATE']
    if state == 'PDF_APPROPRIATE': frequency = friction = None
    row = dict(id=f'{book}-{key}', needId=need or f'{book}:{key}', bookId=book, book=BOOKS[book], pdfPage=pages, printedPage=printed, section=section, content=content, type=typ, classification=state, severity=None if green else severity, frequency=frequency, friction=friction, priority=frequency*friction if frequency and friction else None, appPath=path or ('Original supplied PDF' if state == 'PDF_APPROPRIATE' else 'No usable application reference'), searchQueries=queries or [content], searchable=searchable or ('n/a' if state == 'PDF_APPROPRIATE' else 'no' if not path else 'yes' if state == 'RESOLVED' else 'indirect'), contextLinked='n/a' if state == 'PDF_APPROPRIATE' else context, tableView=view or ('yes' if tableids else 'n/a'), problem=problem, minimalFix=fix, solutionType=solutions or ([] if state == 'RESOLVED' else ['PDF_APPROPRIATE'] if state == 'PDF_APPROPRIATE' else ['QUICK_RULE']), workflows=workflows or ['Dungeon'], evidence={'code': code or ['src/domain/references.ts:405', 'src/domain/references.ts:903'], 'tableIds': tableids or [], 'notes': notes or 'Fresh supplied PDF page text checked against current private bundle, canonical registry and display path. Browser checks are reported separately by the coordinating audit.'})
    rows.append(row)
    return row

def table(book, tid, section, *, state='RESOLVED', problem=None, fix='None.', **kwargs):
    t = tables[tid]
    p = t.get('sourcePage') or t.get('sourcePages')
    if isinstance(p, str): p = [int(n) for n in re.findall(r'\d+', p)]
    return add(book, 'table-'+tid.split('.',1)[1].replace('.', '-'), p, section, t['title'], 'Table', state, problem or 'All table outcomes, dice and relevant effect text are present; canonical reference supports rolling or intentional full-table inspection. A completed table does not imply every surrounding scenario rule is covered.', fix, path='Reference Desk → oracle:'+tid+' → ROLL / TABLE / SOURCE', queries=[t['title']], tableids=[tid], printed=str(t.get('printedPage') or 'Unnumbered fold / cover'), frequency=2, friction=1 if state == 'RESOLVED' else 3, **kwargs)

