    add('heretic','creature-'+slug(name),pages,c.get('context') or name,name,'Creature',state,problem,'None.' if ref else 'Make verified non-numeric-stat source creatures inspectable without manufacturing HP/armor; render its existing specialAbility.',path='Reference Desk → '+ref if ref else 'library.creatures → record stored but not exposed',queries=[name],code=['src/domain/references.ts:91','src/domain/references.ts:557','src/generators/monster.ts:362','src/domain/referenceExecution.ts:61'],solutions=[] if ref else ['MONSTER_REFERENCE'],frequency=3,friction=1 if ref else 5,workflows=['Monster','Dungeon'],printed=str(c.get('source',{}).get('printedPage') or 'Last fold, unnumbered'),need=need)
