ledger=[]
for book in BOOKS:
    source=json.loads((ROOT/f'outputs/pdf-escape-audit/extracted/{book}.json').read_text())
    for p in source['pageText']:
        n=p['pdfPage']; matched=[r for r in rows if r['bookId']==book and n in r['pdfPage']]
        assert matched,(book,n)
        title=(FER_SECTIONS if book=='feretory' else HER_SECTIONS if book=='heretic' else {}).get(n,'Independent / auxiliary source page')
        printed='First fold / unnumbered' if n in [2,3] else str(n-2) if 5<=n<=65 else 'Unnumbered / cover / fold'
        if book=='feretory' and n==66:printed='Inside back cover; no printed number visible (extracted legacy header is not visible)'
        if book=='heretic' and n>=66:printed='Last fold / back cover, unnumbered'
        if book not in ['feretory','heretic']:printed='Source-specific / not ordinary MB pagination'
        ledger.append({'bookId':book,'pdfPage':n,'printedPage':printed,'section':title,'needIds':[r['needId'] for r in matched],'classifications':sorted(set(r['classification'] for r in matched)),'pdfAppropriateExclusion':any(r['classification']=='PDF_APPROPRIATE' for r in matched),'review':'Fresh full-page text read; dense page layouts additionally rendered where referenced in report.'})
assert len({r['id'] for r in rows})==len(rows)
assert all(t in tables for r in rows for t in r['evidence']['tableIds'])
OUT.mkdir(parents=True,exist_ok=True)
(OUT/'supplement-rows.json').write_text(json.dumps(rows,ensure_ascii=False,indent=2)+'\n')
(OUT/'supplement-page-ledger.json').write_text(json.dumps(ledger,ensure_ascii=False,indent=2)+'\n')
summary={b:{s:sum(r['bookId']==b and r['classification']==s for r in rows) for s in ['RESOLVED','PRESENT_BUT_INDIRECT','PARTIAL','MISSING','PDF_APPROPRIATE','SOURCE_UNAVAILABLE']} for b in BOOKS}
print(json.dumps({'rows':len(rows),'pages':len(ledger),'byBook':summary},indent=2))
